package com.example.login_app

import android.os.Bundle
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import com.google.android.material.button.MaterialButton
import com.google.android.material.textfield.TextInputEditText

class MainActivity : AppCompatActivity() {
    private lateinit var bridge: MantraBridge

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        
        // Pure Native Android: Set native XML layout generated by Mantra compiler
        setContentView(R.layout.activity_main)

        bridge = MantraBridge(this) { rawRequest ->
            handleNativeRequest(rawRequest)
        }

        setupNativeListeners()
    }

    private fun setupNativeListeners() {
        // Bind native Material Button to Mantra native action
        val loginBtn = findViewById<MaterialButton?>(R.id.login_btn)
        loginBtn?.setOnClickListener {
            val email = findViewById<TextInputEditText?>(R.id.email_input)?.text?.toString() ?: ""
            Toast.makeText(this, "Signed in via Mantra Native Android UI!", Toast.LENGTH_SHORT).show()
            bridge.dispatchLifecycleEvent("auth_success", "logged_in")
        }
    }

    private fun handleNativeRequest(requestJson: String): String {
        return """{"success":true,"data":{"platform":"android_native","app":"login_app","status":"ready"}}"""
    }
}
